import{_ as t,H as E,f as a,i}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"代码评点02 | 什么是合适TDD的语言和IDE？","description":"","frontmatter":{},"headers":[{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/代码评点02｜什么是合适TDD的语言和IDE？.md","filePath":"徐昊·TDD项目实战70讲/代码评点02｜什么是合适TDD的语言和IDE？.md","lastUpdated":1795563222000}'),s={name:"徐昊·TDD项目实战70讲/代码评点02｜什么是合适TDD的语言和IDE？.md"};function n(r,e,o,D,p,l){return E(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="代码评点02-什么是合适tdd的语言和ide" tabindex="-1">代码评点02 | 什么是合适TDD的语言和IDE？ <a class="header-anchor" href="#代码评点02-什么是合适tdd的语言和ide" aria-label="Permalink to &quot;代码评点02 | 什么是合适TDD的语言和IDE？&quot;">​</a></h1><p>你好，我是徐昊。今天我们继续来进行代码评点。</p><p>上节课我们展示了在 Higher-order function 组合的函数风格下，进行 TDD 的节奏。我们还剩下最后一段类型函数没有做完：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B902/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B902/1.jpeg" alt=""></a></p><p>接下来就是重构的环节：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B902/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B902/2.jpeg" alt=""></a></p><p>重构虽然是修改代码的一种意图，但在 21 世纪的今天，我们讲重构的时候，特指在工具辅助下所做的自动化重构。因而随着使用的工具不同，我们所做的重构也应该有所不同。</p><p>可以说，无论使用什么样的语言，我们都应该找到那个对自动化支持最好的工具，这样才能让整个 TDD 的过程变得更加顺畅。这也是我在这次代码点评中，想特别提醒你注意的一点。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>Higher-order function 函数风格和对象风格在 TDD 的节奏上有什么不同？</p><p>编辑来信</p><ul><li><p>如果你没有来得及参加此次代码评点活动，别担心，还有机会。我们在每个实战项目结束之际，都会开展“代码评点”活动。我们的要求依然是，跟上课程的更新节奏，多动手多实操多思考，最后填写学习反馈的问卷！</p></li><li><p>另外，可以加入我们的读者交流群，及时获取活动信息。也可以关注每节课的末尾部分，我会时不时地插播一些活动信息。</p></li></ul><p>接下来我们将进入实战中的 TDD 环节，也就是使用 TDD 的方式，去实现我们工作中常用的技术框架。我们下节课再见！</p>',13)])])}const B=t(s,[["render",n]]);export{A as __pageData,B as default};
